class Kind(str, Enum):
    """What a node is."""

    SIMPLE_REPEATER = "simple-repeater"
    """forwards, and nothing else"""

    ADVANCED_REPEATER = "advanced-repeater"
    """forwards, serves clients, holds state"""

    COMPANION = "companion"
    """a user's device - the thing a phone connects to"""

    ROOM_SERVER = "room-server"
    """holds posts for clients to collect, and does not forward: a mesh that treats one
    as a repeater overstates its own reach
    """

    SDR_OBSERVER = "sdr-observer"
    """runs no firmware and transmits nothing; captures the summed field at its antenna
    and hands back IQ
    """

    EMITTER = "emitter"
    """interference that is not MeshCore, propagated through the same terrain as
    everything else
    """


